'use strict';
/**
 * test_i18n_key_coverage.js
 * Scans all source files for _t() translation key usages and verifies
 * that all referenced keys exist in both EN and RU dictionaries.
 */
const assert = require('assert');
const fs = require('fs');
const path = require('path');

const { AGY_LOCALE_EN } = require('../locales/en');
const { AGY_LOCALE_RU } = require('../locales/ru');

console.log('=== Starting i18n Key Coverage Tests ===\n');

// Excluded bundles (autogenerated from sources)
const EXCLUDED_BUNDLES = new Set([
  'hud_widget.js',
  path.normalize('patches/account_manager_ui.js'),
  path.normalize('patches/adaptive_retry.js'),
  path.normalize('patches/byok_manager_ui.js'),
  path.normalize('patches/prompt_manager_ui.js'),
  path.normalize('patches/proxy_manager_ui.js'),
  path.normalize('patches/subagent_manager_ui.js'),
  path.normalize('patches/agy_i18n.js')
]);

// Known missing keys baseline (all 20 missing keys resolved in B5)
const KNOWN_MISSING = [].sort();

function getSourceFiles(dir, rootDir) {
  let files = [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relPath = path.relative(rootDir, fullPath);

    if (entry.isDirectory()) {
      if (entry.name === 'node_modules' || entry.name === 'research' || entry.name === 'tests') {
        continue;
      }
      files = files.concat(getSourceFiles(fullPath, rootDir));
    } else if (entry.isFile() && (entry.name.endsWith('.js') || entry.name.endsWith('.css'))) {
      if (EXCLUDED_BUNDLES.has(relPath)) {
        continue;
      }
      files.push(fullPath);
    }
  }
  return files;
}

const scriptsDir = path.resolve(__dirname, '..');
const sourceFiles = getSourceFiles(scriptsDir, scriptsDir);

console.log(`1. Scanning ${sourceFiles.length} source files for _t() calls...`);

const tRegex = /_t\(\s*['"]([a-zA-Z0-9_.]+)['"]\s*[,)]/g;
const foundKeys = new Set();
const keySources = new Map();

for (const file of sourceFiles) {
  const code = fs.readFileSync(file, 'utf8');
  let match;
  while ((match = tRegex.exec(code)) !== null) {
    const key = match[1];
    foundKeys.add(key);
    if (!keySources.has(key)) {
      keySources.set(key, []);
    }
    keySources.get(key).push(path.relative(scriptsDir, file));
  }
}

console.log(`  [✓] Found ${foundKeys.size} unique _t() keys across source files`);

console.log('\n2. Verifying key coverage against en.js and ru.js...');
const missingKeys = [];
const missingEnOnly = [];
const missingRuOnly = [];

for (const key of Array.from(foundKeys).sort()) {
  const inEn = Object.prototype.hasOwnProperty.call(AGY_LOCALE_EN, key);
  const inRu = Object.prototype.hasOwnProperty.call(AGY_LOCALE_RU, key);

  if (!inEn && !inRu) {
    missingKeys.push(key);
  } else if (!inEn) {
    missingEnOnly.push(key);
  } else if (!inRu) {
    missingRuOnly.push(key);
  }
}

assert.strictEqual(missingEnOnly.length, 0, `Keys present in RU but missing in EN: ${missingEnOnly.join(', ')}`);
assert.strictEqual(missingRuOnly.length, 0, `Keys present in EN but missing in RU: ${missingRuOnly.join(', ')}`);

// Compare missing keys against KNOWN_MISSING baseline
const unexpectedMissing = missingKeys.filter(k => !KNOWN_MISSING.includes(k));
const newlyResolved = KNOWN_MISSING.filter(k => !missingKeys.includes(k));

if (unexpectedMissing.length > 0 || newlyResolved.length > 0) {
  const diffMsg = [
    'i18n key coverage drift detected!',
    unexpectedMissing.length > 0 ? `Unexpected missing keys (not in KNOWN_MISSING):\n  - ${unexpectedMissing.join('\n  - ')}` : '',
    newlyResolved.length > 0 ? `Keys now provided in dictionaries (remove from KNOWN_MISSING):\n  - ${newlyResolved.join('\n  - ')}` : ''
  ].filter(Boolean).join('\n');
  assert.fail(diffMsg);
}

assert.deepStrictEqual(missingKeys, KNOWN_MISSING, 'Missing keys must match KNOWN_MISSING baseline exactly');
console.log(`  [✓] Key coverage verified: ${foundKeys.size - missingKeys.length}/${foundKeys.size} keys covered (${missingKeys.length} known missing tracked under TODO B5)`);

console.log('\n=== ALL i18n KEY COVERAGE TESTS PASSED SUCCESSFULLY! ✓ ===\n');
